        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (35, 'Nike Dunk Low', 'Bạn luôn có thể tin tưởng vào một thiết kế kinh điển. Giày Dunk Low kết hợp kiểu phối màu đặc trưng với chất liệu cao cấp, có kết cấu và lớp đệm êm ái mang đến sự thoải mái vượt trội kéo dài. Khả năng phối đồ là vô tận—bạn sẽ mang giày Dunk như thế nào?\n', 3519000.00, 4750650.00, 1, 6, '2026-01-21 00:41:47', 0, 1, NULL)");
