        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (38, 'Adidas Adizero Evo Sl', 'Khám phá cảm giác tốc độ đỉnh cao cùng Giày Chạy Bộ Nam Adidas Adizero Evo Sl\n\nđôi giày lấy cảm hứng từ những siêu phẩm phá vỡ kỷ lục của dòng Adizero trứ danh. Được thiết kế không chỉ dành cho vận động viên mà còn trong phong cách sống hàng ngày, Evo SL kết hợp công nghệ tiên tiến cùng diện mạo táo bạo, mạnh mẽ. Lớp đệm LIGHTSTRIKE PRO đàn hồi ở đế giữa đem lại sự êm ái tối ưu, hoàn trả năng lượng tuyệt vời, nâng bước bạn trên từng chặng đường chinh phục.\n', 4000000.00, 5400000.00, 2, 1, '2026-01-21 08:19:18', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (39, 'Adidas Adizero Boston 13 Neutral', 'Khám phá tốc độ đỉnh cao cùng Giày Chạy Bộ Nam Adidas Adizero Boston 13 Neutral – lựa chọn lý tưởng cho những buổi tập luyện tăng tốc và chuẩn bị thi đấu. Được thiết kế siêu nhẹ với phần thân lưới thoáng khí, đôi giày này giúp bạn vượt qua mọi giới hạn mà vẫn giữ cảm giác dễ chịu, ôm chắc khớp giữa bàn chân. Đế giữa Lightstrike và Lightstrike Pro kết hợp công nghệ ENERGYRODS mang lại độ nảy linh hoạt, hỗ trợ mỗi bước chạy thêm bùng nổ. Đế ngoài Lighttraxion bám chắc trên mọi địa hình cùng lớp Continental™ Rubber chống trượt ở mũi giày, giúp sải bước\n', 3317000.00, 4477950.00, 2, 1, '2026-01-21 08:29:30', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (40, 'Adidas Ultraboost 5', 'Bứt phá từng bước chạy cùng Giày Chạy Bộ Nam Adidas Ultraboost 5 – phiên bản cải tiến với đệm Light BOOST V2 nhẹ hơn, êm hơn và hoàn trả năng lượng vượt trội. Upper PRIMEKNIT co giãn ôm sát bàn chân, kết hợp hệ thống Torsion và gót giày định hình giúp giữ vững chuyển động ổn định. Đế ngoài Continental™ bám đường tối ưu cho mọi cung đường.\n', 4063000.00, 5485050.00, 2, 1, '2026-01-21 08:36:27', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (41, 'Adidas Adistar 3', 'Chinh phục mục tiêu với tốc độ ổn định cùng đôi giày chạy bộ adidas này. Với thiết kế dành cho chạy bộ đường dài, giày có đế giữa REPETITOR cho cảm giác êm ái tối đa và tràn đầy năng lượng trên từng cây số. Thân giày bằng vải lưới thoáng khí giúp lưu thông khí để đôi chân luôn mát mẻ, cùng hệ thống tùy chỉnh độ ôm bên trong giúp cố định bàn chân để tăng cường nâng đỡ trên cự ly dài. Đế ngoài Adiwear cho độ bám chắc chắn và bền bỉ trên suốt đường chạy cự ly dài.\n', 2914000.00, 3933900.00, 2, 1, '2026-01-21 08:45:11', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (42, 'Adidas Adizero Boston 13 ', 'Đánh thức tốc độ với Giày Chạy Bộ Nam Adidas Adizero Boston 13 – trợ thủ tuyệt vời cho những buổi tập chất lượng trước ngày đua. Thiết kế siêu nhẹ, năng động, phần upper lưới thoáng khí ôm gọn bàn chân và giữ chắc phần midfoot, tạo cảm giác tự tin trên từng bước chạy. Đế giữa Lightstrike kết hợp Lightstrike Pro cùng công nghệ ENERGYRODS tăng độ nảy, tiết kiệm sức lực qua từng km. Đế ngoài Lighttraxion bám tốt trên mọi địa hình, phối hợp với lớp Continental™ Rubber chống trượt ở mũi chân, giúp bạn yên tâm bứt tốc.\n', 4000000.00, 5400000.00, 2, 1, '2026-01-21 08:48:48', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (43, 'Adidas Adizero Sl2', 'Khám phá giới hạn bản thân cùng giày chạy bộ nam Adidas Adizero SL2 – lựa chọn hoàn hảo cho những ai đang tìm kiếm hiệu suất, tốc độ và sự thoải mái trong từng sải chân. Phần đế giữa sử dụng Lightstrike Pro – công nghệ đệm cao cấp giúp hoàn trả năng lượng nhanh, mang lại cảm giác bật nhảy nhẹ nhàng và duy trì tốc độ ổn định. Upper bằng vải lưới đơn lớp (mono mesh) siêu nhẹ và thoáng khí, giữ chân luôn khô thoáng khi chạy dài. Với thiết kế linh hoạt, SL2 phù hợp cả luyện tập tốc độ và thi đấu phong trào.\n', 3000000.00, 4050000.00, 2, 1, '2026-01-21 08:54:11', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (44, 'Adidas Supernova Rise 2', 'Giày Chạy Bộ Nam Adidas Supernova Rise 2 là người bạn đồng hành lý tưởng cho những buổi chạy bộ hàng ngày và hành trình chinh phục đường đua. Với đệm Dreamstrike+ siêu nhẹ êm ái, hệ thống Support Rods dẫn hướng chuyển động linh hoạt và thân giày sandwich mesh thoáng khí, đôi giày mang đến cảm giác thoải mái, hỗ trợ tối ưu từ gót đến mũi chân. Được công nhận bởi Hiệp hội Y khoa Bàn chân Hoa Kỳ, đây là lựa chọn hoàn hảo cho đôi chân khỏe mạnh.\n', 3151000.00, 4253850.00, 2, 1, '2026-01-21 09:07:38', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (45, 'Adidas Duramo Speed 2', 'Bứt phá mọi giới hạn cùng Giày Chạy Bộ Nam Adidas Duramo Speed 2 – bạn đồng hành lý tưởng cho mọi cự ly và mục tiêu tập luyện. Thiết kế thể thao năng động với thân giày vải lưới kỹ thuật siêu nhẹ, thoáng khí, ôm chân vững chắc giúp bạn luôn tràn đầy năng lượng trên đường chạy. Đệm Lightstrike đàn hồi tốt kết hợp đế ngoài TPU bám đường vượt trội, hỗ trợ chuyển động linh hoạt trên nhiều bề mặt. Sản phẩm thân thiện môi trường khi sở hữu ít nhất 20% chất liệu tái chế, hướng tới lối sống bền vững nhưng vẫn đảm bảo hiệu năng thể thao tối ưu.\n', 2500000.00, 3375000.00, 2, 1, '2026-01-21 09:13:26', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (46, 'Adidas 4Dfwd 4', 'Chạy quanh thành phố và nâng cao tinh thần thể thao mỗi ngày cùng Giày Chạy Bộ Nam Adidas 4Dfwd 4. Tận hưởng bước chạy mượt mà nhờ đế giữa 4D sử dụng công nghệ 3D có khả năng hấp thụ lực và hỗ trợ chuyển động linh hoạt hơn. Thân giày bằng vải dệt cho độ ôm vừa khít, mang đến cảm giác thoải mái và ổn định khi bạn di chuyển trên đường phố.\n', 4561000.00, 6157350.00, 2, 1, '2026-01-21 09:19:53', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (47, 'Adidas Supernova Stride', 'Giày Chạy Bộ Nam Adidas Supernova Stride được thiết kế để mang lại cho người chạy sự hỗ trợ vừa vặn cho những buổi chạy hàng ngày. Công nghệ Dreamstrike+ với mút foam siêu mềm mại, đã được tái thiết kế - đặt ở phần mũi chân để tạo ra lực đẩy hỗ trợ và tối ưu hóa cảm giác thoải mái. Để hoàn thiện đế giữa, lớp EVA được tăng cường, đảm bảo rằng các chuyển động của bạn vừa linh hoạt vừa ổn định. Cuối cùng, hãy tự tin tiến về phía trước với đế ngoài Adiwear bền bỉ, ma sát tại các vị trí cần thiết.\n', 2654000.00, 3582900.00, 2, 1, '2026-01-21 09:23:23', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (48, 'Adidas Dropset 2 Earth', 'Bất kể mục tiêu của bạn là gì, đôi giày sneaker tập luyện adidas này sẽ giúp bạn chinh phục tất cả. Giày có dáng thấp tạo cảm giác sát đất tối ưu mang lại sự ổn định, tư thế chuẩn và chuyển động tự tin. Đế giữa mật độ kép có phần gót giày cứng hơn giúp truyền lực tối đa và mũi giày mềm hơn mang lại sự linh hoạt.\n', 2902000.00, 3917700.00, 2, 4, '2026-01-21 09:29:52', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (49, 'Adidas Dropset 3 Trainer', 'Bất kể bạn nâng tạ, chống đẩy hay lên xà, đôi giày trainer Dropset 3 luôn mang đến sự nâng đỡ ổn định cần thiết cho các bài tập thể lực. Đế giữa mật độ kép giúp đôi chân luôn êm ái suốt những rep tập cường độ cao, cùng thành đế giày bằng TPU cố định phần giữa bàn chân. Công nghệ adidas HEAT.RDY giữ cho đôi chân luôn mát mẻ kể cả khi buổi tập tăng nhiệt. Với dáng rộng hơn tiêu chuẩn, đôi giày trainer này vẫn ôm thoải mái dù chân có phồng lên sau nhiều giờ nỗ lực.\n', 2902000.00, 3917700.00, 2, 4, '2026-01-21 09:32:09', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (50, 'Adidas Dropset 2 Trainer', 'Cảm giác của thanh tạ đòn trên tay, âm thanh các đĩa tạ va vào nhau, tiếng chuông báo hiệu kỷ lục mới đạt được. Chẳng gì sánh bằng một buổi nâng tạ thành công, và đôi giày tập luyện adidas này mang đến cho bạn phong độ vượt trội trong các buổi tập rèn luyện sức mạnh. Đế giữa chênh lệch độ cao 6 mm tạo nền tảng bằng phẳng và ổn định, giúp bạn căn chỉnh đúng tư thế mỗi lần nâng tạ. Đế giữa mật độ kép mang lại cảm giác thoải mái và ổn định có kiểm soát, cùng đế ngoài Traxion siêu bám cho bạn thế đứng vững chãi.\nLàm từ một loạt chất liệu tái chế, thân giày có chứa tối thiểu 50% thành phần tái chế. Sản phẩm này đại diện cho một trong số rất nhiều các giải pháp của chúng tôi hướng tới chấm dứt rác thải nhựa.\n', 3500000.00, 4725000.00, 2, 4, '2026-01-21 09:35:03', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (51, 'Adidas Rapidmove Adv', 'CGiày tập adidas RapidMove ADV là lựa chọn hoàn hảo cho những ai đang tìm kiếm một đôi giày hỗ trợ chuyển động linh hoạt và ổn định. Thân giày bằng vải dệt kim kỹ thuật với các vùng nâng đỡ giúp ôm sát chân, tạo cảm giác thoải mái và chắc chắn. Lớp đệm Lightstrike siêu nhẹ và đàn hồi giúp bạn di chuyển nhanh nhẹn và linh hoạt hơn. Hệ thống Torsion System bất đối xứng mang lại sự ổn định khi chuyển hướng nhanh và di chuyển đa hướng.\nĐặc biệt, thân giày được làm từ một loạt chất liệu tái chế, có chứa tối thiểu 50% thành phần tái chế. Sản phẩm này là một trong những giải pháp của adidas hướng tới chấm dứt rác thải nhựa.\n', 2654000.00, 3582900.00, 2, 4, '2026-01-21 09:38:47', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (52, 'Adidas Dropset 2', 'Trải nghiệm cảm giác tuyệt vời khi nâng tạ với đôi giày tập luyện adidas Dropset 2. Đôi giày này được thiết kế dành riêng cho các buổi tập rèn luyện sức mạnh, mang đến cho bạn sự ổn định, thoải mái và độ bám tuyệt vời.\nĐế giữa chênh lệch độ cao 6 mm giúp bạn căn chỉnh đúng tư thế mỗi lần nâng tạ, tránh chấn thương. Đế giữa mật độ kép mang lại cảm giác thoải mái và ổn định có kiểm soát, cùng đế ngoài Traxion siêu bám cho bạn thế đứng vững chãi. Thân giày rộng rãi, thoải mái, phù hợp với mọi kích cỡ bàn chân. Hệ thống dây giày tùy chỉnh giúp bạn dễ dàng điều chỉnh độ vừa vặn.\n', 2902000.00, 3917700.00, 2, 4, '2026-01-21 09:41:19', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (53, 'Adidas Dropset Control Trainer M', 'Sức mạnh bắt đầu từ nền tảng vững chắc. Giày Luyện Tập Nam Adidas Dropset Control Trainer M giúp bạn luôn vững vàng khi tập luyện nặng. Thiết kế rộng thoải mái và đế giữa ổn định tạo điểm tựa chắc chắn cho từng động tác nâng tạ. Công nghệ TPU ở giữa bàn chân tăng cường hỗ trợ khi di chuyển linh hoạt. Thân giày lưới giúp feet bạn luôn mát mẻ, thoải mái vượt qua mọi thử thách.\n', 2400000.00, 3240000.00, 2, 4, '2026-01-21 09:44:05', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (54, 'Adidas Dropset Control', 'Bạn đang tìm kiếm đôi giày lý tưởng để nâng cao hiệu suất tập luyện? Giày Luyện Tập Nam Adidas Dropset Control chính là sự lựa chọn hoàn hảo, đặc biết với những ai yêu thích bộ môn gym, giúp bạn tự tin thực hiện các bài tập nặng. Kiểu dáng rộng rãi và đế giữa chắc chắn tạo nền tảng vững chắc khi nâng tạ, trong khi hệ thống hỗ trợ TPU giữa bàn chân mang đến sự ổn định tối đa cho những động tác linh hoạt. Phần thân giày bằng lưới giúp đôi chân luôn mát mẻ và dễ chịu, cho bạn thêm sức mạnh bứt phá mọi giới hạn.\n', 1990000.00, 2686500.00, 2, 4, '2026-01-21 09:48:07', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (55, 'Adidas Dropset 4 Power', 'Giày Luyện Tập Nam Adidas Dropset 4 Power – lựa chọn hoàn hảo cho các bài tập sức mạnh và đa năng. Thiết kế tối ưu giúp giữ thăng bằng và bùng nổ trong từng chuyển động, phù hợp cho luyện tập thể lực, tập tạ, rèn sức bền cơ, hay chạy ngắn.\n', 3500000.00, 4725000.00, 2, 4, '2026-01-21 09:50:44', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (56, 'Adidas Predator League Turf', 'Khi bạn nhắm đến mục tiêu, adidas Predator giúp bạn biến áp lực thành những cú sút chính xác. Với lớp phủ 3D và các vây Strikescale bám dính ở mặt trong, phần trên Hybridfeel của đôi giày bóng đá League này được tối ưu hóa để sút bóng chính xác. Bên dưới, đế cao su với các đinh tán mang lại sự ổn định trên sân cỏ nhân tạo.\n', 1990000.00, 2686500.00, 2, 2, '2026-01-21 09:56:34', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (57, 'Adidas X Crazyfast Club Turf', 'Không gì cản được mỗi khi tốc độ thuần túy kích hoạt. Thay đổi thế trận ngay tức khắc và bỏ lại hàng hậu vệ phía sau với đôi giày adidas X Crazyfast siêu nhẹ. Đôi giày đá bóng này có đế đinh bằng cao su giúp bạn di chuyển đầy tốc độ trên sân cỏ nhân tạo. Mềm mại mà bền bỉ, thân giày bằng vải dệt có lớp phủ cho cảm giác bóng chắc chắn khi bạn đang rê bóng thần tốc. Đế giữa bằng chất liệu EVA tăng cường cảm giác thoải mái.\nSản phẩm này có chứa tối thiểu 20% chất liệu tái chế. Bằng cách tái sử dụng các chất liệu đã được tạo ra, chúng tôi góp phần giảm lãng phí và giảm phụ thuộc vào các nguồn tài nguyên hữu hạn, cũng như giảm phát thải từ các sản phẩm mà chúng tôi sản xuất.\n', 1327000.00, 1791450.00, 2, 2, '2026-01-21 10:02:36', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (58, 'Adidas Predator Elite Tf', 'Không gì cản được mỗi khi tốc độ thuần túy kích hoạt. Thay đổi thế trận ngay tức khắc và bỏ lại hàng hậu vệ phía sau với đôi giày adidas X Crazyfast siêu nhẹ. Đôi giày đá bóng này có đế đinh bằng cao su giúp bạn di chuyển đầy tốc độ trên sân cỏ nhân tạo. Mềm mại mà bền bỉ, thân giày bằng vải dệt có lớp phủ cho cảm giác bóng chắc chắn khi bạn đang rê bóng thần tốc. Đế giữa bằng chất liệu EVA tăng cường cảm giác thoải mái.\nSản phẩm này có chứa tối thiểu 20% chất liệu tái chế. Bằng cách tái sử dụng các chất liệu đã được tạo ra, chúng tôi góp phần giảm lãng phí và giảm phụ thuộc vào các nguồn tài nguyên hữu hạn, cũng như giảm phát thải từ các sản phẩm mà chúng tôi sản xuất.\n', 2902000.00, 3917700.00, 2, 2, '2026-01-21 10:05:25', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (59, 'Adidas Copa Pure 2 League Turf', 'Từ ý tưởng đến thành phẩm, và ngược lại. Kết nối với trái bóng ở mọi cấp độ với adidas Copa Pure 2. Phần trên thoải mái của đôi giày bóng đá League này mang phong cách cổ điển, giúp bạn trông thật đẳng cấp khi thi đấu. Phần mũi giày bằng da bò mang lại cảm giác chạm bóng tinh tế. Bên dưới, đế ngoài cao su với các đinh tán giúp bạn chơi bóng tự tin trên sân cỏ nhân tạo.\n', 1741000.00, 2350350.00, 2, 2, '2026-01-21 10:09:02', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (60, 'Adidas Predator Club Tf', 'Mục tiêu là điều quan trọng nhất trong bóng đá, và những đôi giày này được thiết kế để giúp bạn ghi bàn. Chúng được làm bằng chất liệu tổng hợp mềm mại và thoải mái, với các yếu tố Strikeprint giúp bạn kiểm soát bóng tốt hơn. Đế cao su với gai giúp bạn bám chắc vào mặt sân, để bạn có thể sút bóng chính xác.\nSản phẩm này sử dụng ít nhất 20% vật liệu tái chế. Bằng cách tái sử dụng các vật liệu đã được tạo ra trước đó, chúng tôi giúp giảm lượng rác thải và sự phụ thuộc vào nguồn tài nguyên có hạn.\n', 1327000.00, 1791450.00, 2, 2, '2026-01-21 10:11:39', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (61, 'Adidas F50 Club', 'Khám phá tốc độ thực thụ và bùng nổ cá tính của bạn với Giày Đá Bóng Sân Cỏ Nhân Tạo Nam Adidas F50 Club. Được thiết kế tối ưu cho tốc độ, đôi giày này mang lại cảm giác êm ái, bám sân chắc chắn, giúp bạn luôn tự tin di chuyển và bứt phá trên mọi sân cỏ nhân tạo. Với chất liệu Fiberskin ôm chân và lưỡi gà thoáng khí, adidas F50 là lựa chọn lý tưởng để bạn thể hiện bản lĩnh trên sân đấu.\n', 1600000.00, 2160000.00, 2, 2, '2026-01-21 10:14:56', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (62, 'Adidas Predator League Firm Ground', 'Khi bạn nhắm đến mục tiêu, adidas Predator giúp bạn biến áp lực thành những cú sút chính xác tuyệt đối. Phần trên Hybridfeel của đôi giày bóng đá League này có kết cấu 3D toàn bộ và các vây Strikescale bám dính để cải thiện độ chính xác khi sút. Đế ngoài Controlplate 2.0 giữ cho bạn ổn định trên mặt sân cứng, luôn sẵn sàng tung cú sút.\n', 1990000.00, 2686500.00, 2, 2, '2026-01-21 10:24:21', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (63, 'Adidas Copa Pure 2 Elite Turf', 'Từ ý tưởng đến thành phẩm, và ngược lại. Kết nối với trái bóng ở mọi cấp độ với adidas Copa Pure 2. Đôi giày bóng đá Elite này kết hợp các tính năng hiệu suất cao và các chi tiết cổ điển, mang lại sự thoải mái tuyệt đối. Phần mũi giày bằng da bò chần bông mang lại cảm giác chạm bóng mềm mại. Đế cao su với các đinh tán giúp bạn chơi bóng tự tin và thư thái trên sân cỏ nhân tạo.\n', 2654000.00, 3582900.00, 2, 2, '2026-01-21 10:27:08', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (64, 'Adidas F50 League Firm Ground', 'Giải phóng tốc độ với adidas F50. Được tạo ra để khai thác toàn bộ tiềm năng về khả năng tăng tốc, di chuyển và tốc độ của bạn. Đôi giày bóng đá nhẹ này có phần lưỡi co giãn giúp ôm sát chân bạn, phần trên bằng Fiberskin với họa tiết Sprintgrid ở mũi giày. Phía dưới, đế ngoài Sprintplate 360 được thiết kế để tạo lực đẩy trên nhiều bề mặt.\n', 1990000.00, 2686500.00, 2, 2, '2026-01-21 10:30:41', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (65, 'Adidas Copa Gloro 2 Tf', 'Phong cách Copa classic nay được cải biên dành cho cầu thủ hiện đại. Với những chi tiết đặc trưng của dòng Mundial trong đó có lưỡi gà dạng lật trứ danh, đôi Giày Đá Bóng Unisex Adidas Copa Gloro 2 này sẽ giúp bạn luôn cảm thấy thoải mái nhờ thiết kế thân giày bằng da bò. Bên trên đế đinh bằng cao su dành cho sân cỏ nhân tạo, đế giữa Lightstrike đàn hồi đảm bảo bạn luôn sẵn sàng chuyển động.\n', 2500000.00, 3375000.00, 2, 2, '2026-01-21 10:36:32', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (66, 'Adidas Courtjacontrol 3', 'Tự tin bước vào mỗi trận đấu với giày tennis nam Adidas Courtjacontrol 3 – kết hợp hoàn hảo giữa sự thoải mái, kiểm soát và độ bền. Phần đế giữa Bounce đàn hồi hỗ trợ linh hoạt trong từng bước di chuyển, giúp bạn luôn sẵn sàng bật nhảy, xoay người hoặc trượt chân nhanh nhạy. Công nghệ Torsion System tăng cường ổn định, hỗ trợ chuyển hướng chính xác. Thiết kế upper từ vải lưới thoáng khí giúp giữ mát bàn chân ngay cả khi thi đấu căng thẳng. Đế ngoài Adiwear bền chắc và mũi giày Adituff tăng cường chống mài mòn – lý tưởng cho các trận đấu trên mặt sân cứng.\n', 2400000.00, 3240000.00, 2, 5, '2026-01-21 11:38:50', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (67, 'Adidas Courtflash Speed 2 ', 'Giày Tennis Nam Adidas Courtflash Speed 2 mang phong cách thể thao năng động, nhẹ và linh hoạt, giúp bạn tăng tốc trên sân dễ dàng. Thiết kế upper lưới thoáng khí giúp đôi chân luôn mát mẻ dù vận động với cường độ cao. Công nghệ Adituff chống mài mòn ở mũi giày bảo vệ tối đa khi rê chân trên sân, cho bạn tự tin chơi hết mình. Đặc biệt, sản phẩm sử dụng ít nhất 20% chất liệu tái chế, góp phần giảm rác thải và bảo vệ môi trường.\n', 2400000.00, 2400000.00, 2, 5, '2026-01-21 11:42:33', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (68, 'Adidas Gamecourt 2', 'Giày Tennis Nam Adidas Gamecourt 2 là lựa chọn lý tưởng dành cho những ai yêu thích phong cách năng động và hiệu suất vượt trội. Được sản xuất theo công nghệ Cold Cement tiên tiến, GameCourt 2 mang lại sự nhẹ nhàng, bền bỉ và linh hoạt trên mọi loại mặt sân. Dù bạn đang cải thiện cú đánh hay bứt tốc về phía lưới, giày luôn hỗ trợ tối ưu cho từng chuyển động, để mỗi trận đấu trở nên dễ dàng hơn bao giờ hết. Đừng bỏ lỡ sự kết hợp hoàn hảo giữa chất lượng và niềm đam mê tennis từ adidas dành cho bạn!\n', 2000000.00, 2000000.00, 2, 5, '2026-01-21 11:45:29', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (69, 'Adidas Copa Pure 2 Elite Fg', 'Khám phá sức mạnh của sự kết nối thực sự với Giày Bóng Đá Nam Adidas Copa Pure 2 Elite. Được tinh chỉnh để nâng cao khả năng kiểm soát tuyệt vời, đôi giày này không chỉ là một sản phẩm, mà là một trải nghiệm.\n', 4561000.00, 4561000.00, 2, 2, '2026-01-21 11:49:16', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (70, 'Adidas Predator League Fg', 'Chinh phục mọi thách thức trên sân cỏ với Giày Bóng Đá Nam Adidas Predator League. Được trang bị công nghệ ghi bàn tiên tiến nhất, từ kiểu dáng thoải mái đến phần đế chắc chắn, mỗi chi tiết được tối ưu hóa để nâng cao sức mạnh và kiểm soát bóng của bạn. Hãy sẵn sàng để trải nghiệm một cảm giác độc đáo mỗi khi chạm sân cỏ - đó là lý do tại sao Predator League là sự lựa chọn số một của những người chơi đích thực.\n', 2000000.00, 2000000.00, 2, 2, '2026-01-21 11:53:01', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (71, 'Adidas Samba Inter Milan  ', 'Lan tỏa niềm tự hào Inter Miami CF ở cả trong và ngoài sân futsal. Đôi giày đá bóng adidas Samba này mang sắc màu rực rỡ của bộ trang phục thi đấu thứ ba và huy hiệu CLB. Bất kể nơi đâu, đôi giày phiên bản giới hạn này sẽ giúp bạn luôn thoải mái nhờ thân giày bằng da, mũi giày bằng da lộn classic và đế ngoài bằng cao su siêu bám.\n', 2500000.00, 2500000.00, 2, 2, '2026-01-21 11:55:53', 0, 1, NULL)");
        db.execSQL("INSERT OR IGNORE INTO product (id, name, description, price, original_price, brand_id, shoe_category, added_at, is_discontinue, is_available, product_id) VALUES (72, 'PUMA x HYROX Deviate 4 Shoes', 'Cuộc đua thể lực đỉnh cao đòi hỏi trang bị tối ưu. PUMA x HYROX trở lại với một vòng thi đấu mới, mang đến những thiết kế mới được tuyển chọn đặc biệt dành cho các vận động viên HYROX. Những đôi giày chạy bộ này...\n', 4350000.00, 4350000.00, 3, 1, '2026-01-21 12:08:10', 0, 1, NULL)");
